
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_xc_tpssh_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_tpssh", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.298733529740702e+00, -4.212345325481916e+00, -4.091240705370513e+00, -3.923372863869545e+00, -3.694423212284494e+00, -3.389340022249586e+00, -2.996182118230803e+00, -2.513768182192862e+00, -1.965386380831687e+00, -1.417341483331547e+00, -9.414726827308368e-01, -6.620261381219397e-01, -5.872916166197688e-01, -4.927502055662390e-01, -3.477763364172181e-01, -2.129603314987103e-01, -1.184606887064566e-01, -4.455437919098527e-02, -9.730726591468394e-03, -1.094581933485867e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


